// CSD_RATIONALE_BEGIN
// This strategy alternates between unconstrained and constrained phases to solve math word problems step by step.
// In the unconstrained phase, we allow free-form token generation to explore potential solutions.
// If a "<<" token is encountered, we enter the constrained phase where we enforce grammar rules.
// During the constrained phase, we use constrained sampling to ensure generated tokens follow the grammar.
// We also monitor for dead-end situations to avoid infinite loops and exit the constrained phase when appropriate.
// The strategy ensures that each arithmetic computation is enclosed in << >> delimiters.
// CSD_RATIONALE_END

generated := [];
var steps: nat := 0;
var insideConstrained: bool := false;
var currentConstrained: Prefix := [];

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant |generated| == steps
  invariant helpers.cost == steps
  invariant lm.ValidTokensIdsLogits()
  invariant insideConstrained ==> parser.IsValidPrefix(currentConstrained)
  decreases maxSteps - steps, if insideConstrained then 1 else 0
{
  if !insideConstrained {
    lm.GenerateLogits(prompt + generated);
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    if next == eosToken { break; }
    generated := generated + [next];
    steps := steps + 1;
    if Contains(next, "<<") {
      insideConstrained := true;
      currentConstrained := [];
    }
  } else {
    var narrow := helpers.DeadEndDetection(parser, currentConstrained, 2);
    if parser.IsCompletePrefix(currentConstrained) || narrow {
      insideConstrained := false;
    } else {
      var next, isValid := helpers.ConstrainedStep(lm, parser, prompt, currentConstrained);
      generated := generated + [next];
      steps := steps + 1;
      if isValid {
        currentConstrained := currentConstrained + [next];
        if Contains(next, ">>") { insideConstrained := false; }
      } else {
        insideConstrained := false;
      }
    }
  }
}
cost := helpers.cost;

